package ui

import (
	"bytes"
	_ "embed"
	"image/png"

	"github.com/egoist/mygo/ui"
)

//go:embed logo.png
var logoPNG []byte

var logoBitmap = func() *ui.Bitmap {
	img, err := png.Decode(bytes.NewReader(logoPNG))
	if err != nil {
		return nil
	}
	return ui.NewBitmap(img)
}()

